xpath.script:
tailwind.config = {
    darkMode: "class",
    theme: {
        extend: {
            colors: {
                primary: '#2563eb',
                'primary-light': '#eff6ff',
                'primary-dark': '#1e40af',
                'background-light': '#f8fafc',
                'background-dark': '#020617',
                'text-light-primary': '#1e293b',
                'text-light-secondary': '#64748b',
                'text-dark-primary': '#f8fafc',
                'text-dark-secondary': '#94a3b8',
                'border-light': '#e2e8f0',
                'border-dark': '#1e293b',
            },
            fontFamily: {
                "display": ["Inter", "sans-serif"]
            },
            borderRadius: {
                "DEFAULT": "0.5rem",
                "lg": "0.75rem",
                "xl": "1rem",
                "full": "9999px"
            },
        },
    },
}

body.script:
//
    $(document).ready(function() {
        // Template selection handler
        $('#templateSelect').on('change', function() {
            const templateId = $(this).val();
            const warehouseName = $(this).find('option:selected').data('warehouse');

            if (!templateId) {
                $('#productsSection').hide();
                $('#submitButtons').hide();
                $('#locationDisplay').val('');
                return;
            }

            // Update warehouse display
            $('#locationDisplay').val(warehouseName || '');

            // Show loading spinner
            $('#loadingSpinner').show();
            $('#productsTableContainer').hide();
            $('#productsSection').show();

            // AJAX call to get products
            $.ajax({
                url: '/trcf_fnb_inventory/get_template_products',
                type: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        template_id: parseInt(templateId)
                    }
                }),
                success: function(response) {
                    $('#loadingSpinner').hide();

                    if (response.error) {
                        alert('Lỗi: ' + (response.error.data?.message || response.error.message || 'Không thể tải sản phẩm'));
                        return;
                    }

                    const result = response.result;
                    if (result.error) {
                        alert('Lỗi: ' + result.error);
                        return;
                    }

                    // Render products table
                    renderProductsTable(result.products);
                    $('#productsTableContainer').show();
                    $('#submitButtons').show();
                },
                error: function(xhr, status, error) {
                    $('#loadingSpinner').hide();
                    console.error('AJAX Error:', error);
                    alert('Lỗi kết nối: ' + error);
                }
            });
        });

        function renderProductsTable(products) {
            const tbody = $('#productsTableBody');
            tbody.empty();

            if (!products || products.length === 0) {
                tbody.append(`
                    <tr>
                        <td colspan="5" class="text-center py-8 text-gray-500">
                            Không có sản phẩm nào trong template này
                        </td>
                    </tr>
                `);
                return;
            }

            products.forEach(function(product) {
                // Fallback for transition period (when server not yet restarted)
                const sysQtyTarget = typeof product.system_qty_target !== 'undefined' ? product.system_qty_target : (product.system_qty || 0);
                const sysQtyBase = typeof product.system_qty_base !== 'undefined' ? product.system_qty_base : sysQtyTarget;
                const minQtyBase = typeof product.min_qty_base !== 'undefined' ? product.min_qty_base : null;
                const maxQtyBase = typeof product.max_qty_base !== 'undefined' ? product.max_qty_base : null;

                // Determine color for system_qty using BASE units
                let systemQtyColorClass = '';
                if (minQtyBase != null && maxQtyBase != null) {
                    if (sysQtyBase < minQtyBase) {
                        systemQtyColorClass = 'text-red-600 font-bold';
                    } else if (sysQtyBase <= maxQtyBase) {
                        systemQtyColorClass = 'text-emerald-600 font-bold';
                    } else {
                        systemQtyColorClass = 'text-blue-600 font-bold';
                    }
                }

                const row = $(
                    '<tr class="border-b border-border-light dark:border-border-dark">' +
                        '<td class="whitespace-nowrap py-4 pl-4 pr-3 text-sm font-medium sm:pl-0">' +
                            escapeHtml(product.product_name) +
                        '</td>' +
                        '<td class="whitespace-nowrap px-3 py-4 text-sm">' +
                            escapeHtml(product.uom_name) +
                        '</td>' +
                        '<td class="px-3 py-4 text-xs ' + systemQtyColorClass + '">' +
                            (product.system_display || sysQtyTarget.toFixed(2)) +
                        '</td>' +
                        '<td class="px-3 py-4 text-xs text-text-light-secondary dark:text-text-dark-secondary">' +
                            (product.min_display || '-') +
                        '</td>' +
                        '<td class="px-3 py-4 text-xs text-text-light-secondary dark:text-text-dark-secondary">' +
                            (product.max_display || '-') +
                        '</td>' +
                        '<td class="whitespace-nowrap px-3 py-4 text-sm">' +
                            '<input type="number" ' +
                                   'name="actual_qty_' + product.product_id + '" ' +
                                   'data-product-id="' + product.product_id + '" ' +
                                   'data-system-qty="' + sysQtyTarget + '" ' +
                                   'step="0.01" ' +
                                   'min="0" ' +
                                   'value="' + sysQtyTarget.toFixed(2) + '" ' +
                                   'class="actual-qty-input form-input w-24 rounded-lg text-text-light-primary dark:text-white focus:outline-none focus:ring-2 focus:ring-primary/50 border-border-light dark:border-border-dark bg-white dark:bg-slate-900 focus:border-primary dark:focus:border-primary text-sm p-2" />' +
                            '<input type="hidden" name="system_qty_' + product.product_id + '" value="' + sysQtyTarget + '" />' +
                            '<input type="hidden" name="uom_id_' + product.product_id + '" value="' + product.uom_id + '" />' +
                        '</td>' +
                        '<td class="whitespace-nowrap px-3 py-4 text-sm font-medium difference-cell">' +
                            '0.00' +
                        '</td>' +
                        '<td class="px-3 py-4 text-sm font-bold text-primary dark:text-blue-400">' +
                            (product.to_order_display || '-') +
                        '</td>' +
                    '</tr>'
                );
                tbody.append(row);
            });

            // Attach input event handlers
            $('.actual-qty-input').on('input', function() {
                calculateDifference($(this));
            });
        }

        function calculateDifference($input) {
            const systemQty = parseFloat($input.data('system-qty')) || 0;
            const actualQty = parseFloat($input.val()) || 0;
            const difference = actualQty - systemQty;

            const $diffCell = $input.closest('tr').find('.difference-cell');
            $diffCell.text(difference.toFixed(2));

            // Apply color classes
            $diffCell.removeClass('difference-positive difference-negative');
            if (difference > 0) {
                $diffCell.addClass('difference-positive');
            } else if (difference < 0) {
                $diffCell.addClass('difference-negative');
            }
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, function(m) { return map[m]; });
        }

         // Mobile Menu Logic
        const mobileMenuBtn = document.getElementById('mobile-menu-btn');
        const sidebarWrapper = document.getElementById('sidebar-wrapper');
        const mobileOverlay = document.getElementById('mobile-overlay');

        function toggleMobileMenu() {
            if (!sidebarWrapper) return;
            const isOpen = !sidebarWrapper.classList.contains('-translate-x-full');
            if (isOpen) {
                sidebarWrapper.classList.add('-translate-x-full');
                mobileOverlay.classList.add('hidden');
                mobileOverlay.classList.remove('opacity-100');
                document.body.style.overflow = '';
            } else {
                sidebarWrapper.classList.remove('-translate-x-full');
                mobileOverlay.classList.remove('hidden');
                setTimeout(() => mobileOverlay.classList.add('opacity-100'), 0);
                document.body.style.overflow = 'hidden';
            }
        }

        if (mobileMenuBtn) {
            mobileMenuBtn.addEventListener('click', toggleMobileMenu);
        }
        if (mobileOverlay) {
            mobileOverlay.addEventListener('click', toggleMobileMenu);
        }

        // Form validation before submit
        $('#inventoryCheckForm').on('submit', function(e) {
            const templateId = $('#templateSelect').val();
            if (!templateId) {
                e.preventDefault();
                alert('Vui lòng chọn template');
                return false;
            }

            // Disable submit button to prevent double submission
            $('#submitBtn').prop('disabled', true).text('Đang xử lý...');
            return true;
        });
    });
//
